// Package codec provides a shared little-endian binary encoder (Writer) and
// decoder (Reader) used by the Go client library.
package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
	"runtime"
)

// Reader is a binary deserializer that reads sequentially from a byte slice
// using little-endian encoding. It accumulates errors silently: once an error
// is set, all subsequent reads become no-ops that return zero values without
// overwriting the stored error.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader that reads from payload.
func NewReader(payload []byte) *Reader {
	return &Reader{buf: payload}
}

// overrun records an overrun error attributing it to the caller of the read
// method. The skip is chosen so that runtime.Caller points at the user code
// invoking the public read method.
func (r *Reader) overrun(need int) {
	if r.err != nil {
		return
	}
	_, file, line, ok := runtime.Caller(2)
	if !ok {
		file, line = "?", 0
	}
	r.err = fmt.Errorf("reader: need %d bytes but only %d remaining at %s:%d",
		need, r.Remaining(), file, line)
}

// ensure reports whether n more bytes can be read. If not, it records an
// overrun error. It also returns false if an error is already set.
func (r *Reader) ensure(n int) bool {
	if r.err != nil {
		return false
	}
	if n < 0 || r.pos+n > len(r.buf) {
		r.overrun(n)
		return false
	}
	return true
}

// U8 reads a single byte as a uint8.
func (r *Reader) U8() uint8 {
	if !r.ensure(1) {
		return 0
	}
	v := r.buf[r.pos]
	r.pos++
	return v
}

// U16 reads 2 bytes as a little-endian uint16.
func (r *Reader) U16() uint16 {
	if !r.ensure(2) {
		return 0
	}
	v := binary.LittleEndian.Uint16(r.buf[r.pos:])
	r.pos += 2
	return v
}

// U32 reads 4 bytes as a little-endian uint32.
func (r *Reader) U32() uint32 {
	if !r.ensure(4) {
		return 0
	}
	v := binary.LittleEndian.Uint32(r.buf[r.pos:])
	r.pos += 4
	return v
}

// U64 reads 8 bytes as a little-endian uint64.
func (r *Reader) U64() uint64 {
	if !r.ensure(8) {
		return 0
	}
	v := binary.LittleEndian.Uint64(r.buf[r.pos:])
	r.pos += 8
	return v
}

// F32 reads 4 bytes as an IEEE 754 little-endian float32.
func (r *Reader) F32() float32 {
	if !r.ensure(4) {
		return 0
	}
	v := math.Float32frombits(binary.LittleEndian.Uint32(r.buf[r.pos:]))
	r.pos += 4
	return v
}

// Str reads exactly n bytes and returns them as a string, with no length
// prefix.
func (r *Reader) Str(n int) string {
	if !r.ensure(n) {
		return ""
	}
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// U32LenStr reads a 4-byte little-endian uint32 length prefix followed by that
// many bytes as a string.
func (r *Reader) U32LenStr() string {
	if !r.ensure(4) {
		return ""
	}
	n := int(binary.LittleEndian.Uint32(r.buf[r.pos:]))
	if !r.ensure(4 + n) {
		return ""
	}
	r.pos += 4
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// U8LenStr reads a 1-byte uint8 length prefix followed by that many bytes as a
// string.
func (r *Reader) U8LenStr() string {
	if !r.ensure(1) {
		return ""
	}
	n := int(r.buf[r.pos])
	if !r.ensure(1 + n) {
		return ""
	}
	r.pos++
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// Raw reads exactly n bytes and returns them as a []byte.
func (r *Reader) Raw(n int) []byte {
	if !r.ensure(n) {
		return nil
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	return b
}

// Obj reads n bytes and passes them to v.UnmarshalBinary. Any error returned by
// UnmarshalBinary is stored in the Reader.
func (r *Reader) Obj(n int, v encoding.BinaryUnmarshaler) {
	if !r.ensure(n) {
		return
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	if err := v.UnmarshalBinary(b); err != nil {
		if r.err == nil {
			r.err = err
		}
	}
}

// Remaining returns the number of bytes not yet consumed.
func (r *Reader) Remaining() int {
	return len(r.buf) - r.pos
}

// Err returns the accumulated error, or nil if none occurred.
func (r *Reader) Err() error {
	return r.err
}
