package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
	"runtime"
)

// Writer is a binary serializer that appends sequentially to an internal byte
// slice using little-endian encoding. It accumulates errors silently: once an
// error is set, all subsequent writes become no-ops that leave the buffer
// unchanged without overwriting the stored error.
type Writer struct {
	p   []byte
	err error
}

// NewWriter returns an empty Writer.
func NewWriter() *Writer {
	return &Writer{}
}

// NewWriterCap returns a Writer whose buffer is pre-allocated with capacity for
// at least n bytes, so that writes totaling n bytes do not cause reallocation.
func NewWriterCap(n int) *Writer {
	if n < 0 {
		n = 0
	}
	return &Writer{p: make([]byte, 0, n)}
}

// setErr records err (attributed to the caller of the write method) unless an
// error is already set.
func (w *Writer) setErr(err error) {
	if w.err == nil {
		w.err = err
	}
}

// callerf formats a message with the caller's file:line appended. The skip is
// chosen so that runtime.Caller points at the user code invoking the public
// write method.
func callerf(format string, args ...any) error {
	_, file, line, ok := runtime.Caller(2)
	if !ok {
		file, line = "?", 0
	}
	return fmt.Errorf(format+" at %s:%d", append(args, file, line)...)
}

// U8 appends a single byte.
func (w *Writer) U8(v uint8) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, v)
}

// U16 appends 2 bytes in little-endian order.
func (w *Writer) U16(v uint16) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint16(w.p, v)
}

// U32 appends 4 bytes in little-endian order.
func (w *Writer) U32(v uint32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, v)
}

// U64 appends 8 bytes in little-endian order.
func (w *Writer) U64(v uint64) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint64(w.p, v)
}

// F32 appends 4 bytes as an IEEE 754 little-endian float32.
func (w *Writer) F32(v float32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, math.Float32bits(v))
}

// Str appends the raw bytes of s with no length prefix.
func (w *Writer) Str(s string) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, s...)
}

// U32LenStr appends a 4-byte little-endian uint32 length prefix followed by the
// string bytes.
func (w *Writer) U32LenStr(s string) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, uint32(len(s)))
	w.p = append(w.p, s...)
}

// U8LenStr appends a 1-byte uint8 length prefix followed by the string bytes.
// If the string is longer than 255 bytes an error is recorded and the buffer is
// left unchanged.
func (w *Writer) U8LenStr(s string) {
	if w.err != nil {
		return
	}
	if len(s) > 255 {
		w.setErr(callerf("string length %d exceeds 255", len(s)))
		return
	}
	w.p = append(w.p, uint8(len(s)))
	w.p = append(w.p, s...)
}

// Raw appends all bytes from b.
func (w *Writer) Raw(b []byte) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, b...)
}

// Obj marshals v via v.MarshalBinary and appends the returned bytes. If
// MarshalBinary returns an error it is stored with the caller's file:line and
// the buffer is left unchanged.
func (w *Writer) Obj(v encoding.BinaryMarshaler) {
	if w.err != nil {
		return
	}
	b, err := v.MarshalBinary()
	if err != nil {
		w.setErr(callerf("writer: marshal object failed: %v", err))
		return
	}
	w.p = append(w.p, b...)
}

// Bytes returns the accumulated buffer. If an error has been recorded it returns
// an empty (zero-length) slice.
func (w *Writer) Bytes() []byte {
	if w.err != nil {
		return []byte{}
	}
	return w.p
}

// Err returns the accumulated error, or nil if none occurred.
func (w *Writer) Err() error {
	return w.err
}
